package main

import (
	"bytes"
	"fmt"
	"go/format"
	"regexp"
	"slices"
	"strconv"
	"strings"

	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/reflect/protoreflect"
)

const (
	generatedHeader   = "// Code generated by protoc-gen-crd. DO NOT EDIT.\n\n"
	apiextensionsPath = "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"
)

var (
	versionPattern = regexp.MustCompile(`^v[0-9]+((alpha|beta)[0-9]*)?$`)
	notAlphaNum    = regexp.MustCompile(`[^a-z0-9]`)
)

// imports names the packages a generated file uses after their path (`backendv1`, `durationpb`), where protogen would
// call every flock package `v1`.
type imports struct {
	aliases map[protogen.GoImportPath]string
	taken   map[string]bool
}

func newImports() *imports {
	return &imports{aliases: map[protogen.GoImportPath]string{}, taken: map[string]bool{}}
}

func (im *imports) qualify(ident protogen.GoIdent) string {
	if ident.GoImportPath == "" {
		return ident.GoName
	}
	return im.pkg(ident.GoImportPath) + "." + ident.GoName
}

func (im *imports) pkg(path protogen.GoImportPath) string {
	if alias, known := im.aliases[path]; known {
		return alias
	}
	segments := strings.Split(string(path), "/")
	used := 1
	if versionPattern.MatchString(segments[len(segments)-1]) {
		used = 2
	}
	alias := aliasOf(segments, used)
	for im.taken[alias] && used < len(segments) {
		used++
		alias = aliasOf(segments, used)
	}
	im.aliases[path] = alias
	im.taken[alias] = true
	return alias
}

func aliasOf(segments []string, used int) string {
	joined := strings.Join(segments[len(segments)-used:], "")
	return notAlphaNum.ReplaceAllString(strings.ToLower(joined), "")
}

func (im *imports) assemble(body *bytes.Buffer) ([]byte, error) {
	var source bytes.Buffer
	source.WriteString(generatedHeader)
	source.WriteString("package v1alpha1\n\n")
	paths := make([]string, 0, len(im.aliases))
	for path := range im.aliases {
		paths = append(paths, string(path))
	}
	slices.Sort(paths)
	if len(paths) > 0 {
		source.WriteString("import (\n")
		for _, path := range paths {
			fmt.Fprintf(&source, "\t%s %q\n", im.aliases[protogen.GoImportPath(path)], path)
		}
		source.WriteString(")\n\n")
	}
	source.Write(body.Bytes())
	formatted, err := format.Source(source.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated code: %w\n%s", err, source.String())
	}
	return formatted, nil
}

func renderSpec(group *fileGroup) ([]byte, error) {
	im := newImports()
	var body bytes.Buffer
	for _, enum := range group.enums {
		writeEnum(&body, enum)
	}
	for _, t := range group.types {
		writeType(&body, im, t)
	}
	return im.assemble(&body)
}

func writeDoc(body *bytes.Buffer, doc string) {
	if doc == "" {
		return
	}
	for line := range strings.SplitSeq(doc, "\n") {
		line = strings.TrimPrefix(line, " ")
		// a line starting with + would read as a marker
		if strings.HasPrefix(line, "+") {
			line = "\\" + line
		}
		body.WriteString(strings.TrimRight("// "+line, " ") + "\n")
	}
}

func writeMarkers(body *bytes.Buffer, markers []string, rules []celRule) {
	for _, marker := range markers {
		body.WriteString("// +" + marker + "\n")
	}
	for _, rule := range rules {
		fmt.Fprintf(body, "// +kubebuilder:validation:XValidation:rule=%s,message=%s\n", strconv.Quote(rule.rule),
			strconv.Quote(rule.message))
	}
}

func writeEnum(body *bytes.Buffer, enum *goEnum) {
	writeDoc(body, comment(enum.enum.Comments.Leading))
	values := make([]string, 0, len(enum.values))
	for _, value := range enum.values {
		values = append(values, value.value)
	}
	writeMarkers(body, []string{"kubebuilder:validation:Enum=" + strings.Join(values, ";")}, nil)
	fmt.Fprintf(body, "type %s string\n\nconst (\n", enum.name)
	for _, value := range enum.values {
		writeDoc(body, comment(value.proto.Comments.Leading))
		fmt.Fprintf(body, "%s %s = %q\n", value.constName, enum.name, value.value)
	}
	body.WriteString(")\n\n")
}

func writeType(body *bytes.Buffer, im *imports, t *goType) {
	writeDoc(body, t.doc)
	writeMarkers(body, nil, t.celRules)
	fmt.Fprintf(body, "type %s struct {\n", t.name)
	for i, field := range t.fields {
		if i > 0 {
			body.WriteString("\n")
		}
		writeDoc(body, field.doc)
		writeMarkers(body, field.markers, field.celRules)
		fmt.Fprintf(body, "%s %s `json:\"%s%s\"`\n", field.goName, fieldType(im, field), field.jsonName, field.tag)
	}
	body.WriteString("}\n\n")
}

func fieldType(im *imports, field *goField) string {
	elem := im.qualify(field.elem)
	switch {
	case field.shape == shapeMap:
		return "map[string]string"
	case field.list:
		return "[]" + elem
	case field.pointer:
		return "*" + elem
	}
	return elem
}

// converter writes the ToProto methods. Each conversion error names the JSON path of the field, so a status condition
// tells the user what to fix.
type converter struct {
	im   *imports
	body bytes.Buffer
}

func renderConvert(group *fileGroup) ([]byte, error) {
	c := &converter{im: newImports()}
	for _, enum := range group.enums {
		c.writeEnum(enum)
	}
	for _, t := range group.types {
		if t.anyField != nil {
			c.writeAnyWrapper(t)
			continue
		}
		c.writeMessage(t)
	}
	return c.im.assemble(&c.body)
}

func (c *converter) p(pattern string, args ...any) {
	fmt.Fprintf(&c.body, pattern+"\n", args...)
}

func (c *converter) writeEnum(enum *goEnum) {
	protoType := c.im.qualify(enum.enum.GoIdent)
	c.p("func (e %s) toProto() (%s, error) {", enum.name, protoType)
	c.p("switch e {")
	c.p(`case "":`)
	c.p("return 0, nil")
	for _, value := range enum.values {
		c.p("case %s:", value.constName)
		c.p("return %s, nil", c.im.qualify(value.proto.GoIdent))
	}
	c.p("}")
	c.p(`return 0, %s("unknown value %%q", e)`, c.fmt("Errorf"))
	c.p("}\n")
}

func (c *converter) fmt(name string) string {
	return c.im.pkg("fmt") + "." + name
}

func (c *converter) writeAnyWrapper(t *goType) {
	c.p("// ToProto packs the extension that is set, nil when none is.")
	c.p("func (in *%s) ToProto(ctx %s.Context, refs Resolver) (*%s.Any, error) {", t.name, c.im.pkg("context"),
		c.im.pkg("google.golang.org/protobuf/types/known/anypb"))
	for _, member := range t.fields {
		c.p("if in.%s != nil {", member.goName)
		c.p("extension, err := in.%s.ToProto(ctx, refs)", member.goName)
		c.wrapError(member.jsonName)
		c.p("return %s.New(extension)", c.im.pkg("google.golang.org/protobuf/types/known/anypb"))
		c.p("}")
	}
	c.p("return nil, nil")
	c.p("}\n")
}

func (c *converter) writeMessage(t *goType) {
	protoType := c.im.qualify(t.message.GoIdent)
	c.p("// ToProto converts to the message the controller takes, refs giving the uuid of each referenced object.")
	c.p("func (in *%s) ToProto(ctx %s.Context, refs Resolver) (*%s, error) {", t.name, c.im.pkg("context"), protoType)
	c.p("out := &%s{}", protoType)
	for _, field := range t.fields {
		// a field with no proto field is an override's reference, the reconciler handles it
		if field.source == nil {
			continue
		}
		c.writeField(field)
	}
	c.p("return out, nil")
	c.p("}\n")
}

func (c *converter) wrapError(path string) {
	c.p("if err != nil {")
	c.p(`return nil, %s("%s: %%w", err)`, c.fmt("Errorf"), path)
	c.p("}")
}

func (c *converter) wrapIndexedError(path string) {
	c.p("if err != nil {")
	c.p(`return nil, %s("%s[%%d]: %%w", i, err)`, c.fmt("Errorf"), path)
	c.p("}")
}

// assign sets the proto field, through the wrapper type of its oneof when it has one.
func (c *converter) assign(field *goField, value string) {
	source := field.source
	if source.Oneof != nil && !source.Oneof.Desc.IsSynthetic() {
		c.p("out.%s = &%s{%s: %s}", source.Oneof.GoName, c.im.qualify(source.GoIdent), source.GoName, value)
		return
	}
	c.p("out.%s = %s", source.GoName, value)
}

// open starts the block a field converts in: under a nil or zero check when the field may be absent, a bare block
// otherwise so each field keeps its own variables. It returns the expression of the value.
func (c *converter) open(field *goField) string {
	in := "in." + field.goName
	switch {
	case field.pointer:
		c.p("if %s != nil {", in)
		return "*" + in
	case field.shape == shapeDuration || field.shape == shapeWrapper:
		c.p("if %s != 0 {", in)
	default:
		c.p("{")
	}
	return in
}

func (c *converter) writeField(field *goField) {
	in := "in." + field.goName
	switch {
	case field.shape == shapeMap:
		c.p("out.%s = %s.Clone(%s)", field.source.GoName, c.im.pkg("maps"), in)
	case field.list:
		c.writeList(field)
	case field.shape == shapeScalar && !field.pointer, field.shape == shapeBytes:
		c.assign(field, castScalar(field.source.Desc.Kind(), in))
	default:
		value := c.open(field)
		c.writeValue(field, value)
		c.p("}")
	}
}

func (c *converter) writeValue(field *goField, value string) {
	in := "in." + field.goName
	switch field.shape {
	case shapeScalar, shapeBool, shapeBytes:
		c.assign(field, castScalar(field.source.Desc.Kind(), value))
	case shapeEnum:
		c.p("value, err := %s.toProto()", in)
		c.wrapError(field.jsonName)
		c.assign(field, "value")
	case shapeDuration:
		c.assign(field, fmt.Sprintf("%s.New(%s.Duration(%s) * %s.Millisecond)",
			c.im.pkg("google.golang.org/protobuf/types/known/durationpb"), c.im.pkg("time"), value, c.im.pkg("time")))
	case shapeWrapper:
		c.assign(field, c.wrapperValue(field, value))
	case shapeMessage, shapeAny:
		c.p("value, err := %s.ToProto(ctx, refs)", in)
		c.wrapError(field.jsonName)
		c.assign(field, "value")
	case shapeStruct:
		c.p("value := &%s.Struct{}", c.im.pkg("google.golang.org/protobuf/types/known/structpb"))
		c.p("err := %s.Unmarshal(%s.Raw, value)", c.im.pkg("google.golang.org/protobuf/encoding/protojson"), in)
		c.wrapError(field.jsonName)
		c.assign(field, "value")
	case shapeReference:
		c.p("value, err := refs.UUID(ctx, Kind%s, %s)", field.kind, value)
		c.wrapError(field.jsonName)
		c.assign(field, "value")
	}
}

func (c *converter) wrapperValue(field *goField, value string) string {
	wrapperspb := c.im.pkg("google.golang.org/protobuf/types/known/wrapperspb")
	switch field.source.Message.Desc.FullName() {
	case "google.protobuf.UInt32Value":
		return fmt.Sprintf("%s.UInt32(uint32(%s))", wrapperspb, value)
	case "google.protobuf.Int32Value":
		return fmt.Sprintf("%s.Int32(%s)", wrapperspb, value)
	case "google.protobuf.BoolValue":
		return fmt.Sprintf("%s.Bool(%s)", wrapperspb, value)
	}
	return fmt.Sprintf("%s.String(%s)", wrapperspb, value)
}

func (c *converter) writeList(field *goField) {
	in := "in." + field.goName
	out := "out." + field.source.GoName
	switch field.shape {
	case shapeMessage:
		c.p("for i := range %s {", in)
		c.p("value, err := %s[i].ToProto(ctx, refs)", in)
	case shapeEnum:
		c.p("for i := range %s {", in)
		c.p("value, err := %s[i].toProto()", in)
	case shapeReference:
		c.p("for i := range %s {", in)
		c.p("value, err := refs.UUID(ctx, Kind%s, %s[i])", field.kind, in)
	default:
		if castScalar(field.source.Desc.Kind(), "x") == "x" {
			c.p("%s = %s.Clone(%s)", out, c.im.pkg("slices"), in)
			return
		}
		c.p("for _, item := range %s {", in)
		c.p("%s = append(%s, %s)", out, out, castScalar(field.source.Desc.Kind(), "item"))
		c.p("}")
		return
	}
	c.wrapIndexedError(field.jsonName)
	c.p("%s = append(%s, value)", out, out)
	c.p("}")
}

// castScalar converts a CRD scalar to its proto type, the CRD having no unsigned ints.
func castScalar(kind protoreflect.Kind, value string) string {
	switch kind {
	case protoreflect.Uint32Kind:
		return "uint32(" + value + ")"
	case protoreflect.Uint64Kind:
		return "uint64(" + value + ")"
	}
	return value
}
